  it.todo("print(p.next_lex())");
  // text that is not a string
  //   print(p.prev_lex())
  //   => [3, 1]
  it.todo("print(p.prev_lex())");
  it("a.members", () => {
    expect(sympyMatches([rational(1), rational(2), rational(3), rational(4), rational(5)], '(1, 2, 3, 4, 5)')).toBe(true);
  });
  // a primitive result that no library call returned
  //   a.RGS
  //   => (0, 0, 1, 2, 2)
  it.todo("a.RGS");
  it("a + 1", () => {
    expect(sympyStr(new Partition([rational(1), rational(2)], [rational(3)], [rational(4), rational(5)]).add(1))).toBe('Partition({3}, {4}, {5}, {1, 2})');
  });
  it("a.rank", () => {
    expect(sympyStr(new Partition([rational(1), rational(2)], [rational(3)]).rank)).toBe('1');
  });
  it("(a + 1).rank", () => {
    expect(sympyStr(new Partition([rational(1), rational(3)], [rational(2)]).rank)).toBe('2');
  });
  it("(a + 100).rank", () => {
    expect(sympyStr(new Partition([rational(1), rational(2)], [rational(3)]).rank)).toBe('1');
  });
  it("a <= a (2)", () => {
    expect(sympyStr(new Partition([rational(1), rational(2)], [rational(3), rational(4), rational(5)]).le(new Partition([rational(1), rational(2)], [rational(3), rational(4), rational(5)])))).toBe('True');
  });
  it("a <= b", () => {
    expect(sympyStr(new Partition([rational(1), rational(2)], [rational(3), rational(4), rational(5)]).le(new Partition([rational(1)], [rational(2), rational(3)], [rational(4)], [rational(5)])))).toBe('True');
  });
  it("a < b (2)", () => {
    expect(sympyStr(new Partition([rational(1), rational(2)], [rational(3), rational(4), rational(5)]).lt(new Partition([rational(1)], [rational(2), rational(3)], [rational(4)], [rational(5)])))).toBe('True');
  });
  it("a.partition", () => {
    expect(sympyStr([[rational(1), rational(2)], [rational(3)]])).toBe('[[1, 2], [3]]');
  });
